package edu.demo.exam;

import edu.demo.exam.algorithm.*;import edu.demo.exam.model.*;import edu.demo.exam.util.*;
import javafx.application.Application;import javafx.collections.FXCollections;import javafx.geometry.*;import javafx.scene.*;import javafx.scene.chart.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.scene.paint.Color;import javafx.scene.shape.*;import javafx.stage.*;
import java.nio.file.Path;import java.util.*;

/** JavaFX application for demonstrating capacitated exam graph colouring. */
public class Main extends Application {
 private ConflictGraph graph;private int capacity=2;private Timetable greedy,exact;private BorderPane root;private TextArea manual;private TextField nField,rField,densityField,seedField,limitField;private Label status,stats;private ComboBox<String> resultChoice;private VBox graphPane,timetablePane;private TabPane tabs;
 @Override public void start(Stage stage){stage.setTitle("Exam Timetable | Graph Colouring Studio");root=new BorderPane();root.setPadding(new Insets(20));root.setStyle("-fx-background-color: #f4f6fb;");root.setTop(header());root.setLeft(inputs());tabs=new TabPane();Tab overview=new Tab("Schedule",workspace());overview.setClosable(false);Tab analysis=new Tab("Performance",new VBox(14,heading("Algorithm comparison"),new Label("Benchmarks reuse the same seeded graph for both solvers. Exact search has a per-case time limit."),benchmarkButton()));analysis.setClosable(false);tabs.getTabs().addAll(overview,analysis);root.setCenter(tabs);status=new Label("Ready · Enter a graph or generate a random one.");status.setStyle("-fx-text-fill:#516078; -fx-padding:12 0 0 0;");root.setBottom(status);stage.setScene(new Scene(root,1240,850));stage.show();loadExample();}
 private Node header(){VBox box=new VBox(5);Label title=new Label("Exam Timetable Studio");title.setStyle("-fx-font-size:27px;-fx-font-weight:800;-fx-text-fill:#17243b;");Label sub=new Label("Capacitated graph colouring · DSatur heuristic vs exact branch-and-bound");sub.setStyle("-fx-text-fill:#65738a;-fx-font-size:13px;");box.getChildren().addAll(title,sub);box.setPadding(new Insets(0,0,18,0));return box;}
 private Node inputs(){VBox p=new VBox(12);p.setPrefWidth(320);p.setPadding(new Insets(16));p.setStyle(card());nField=field("Courses", "8");rField=field("Halls per slot (R)","3");densityField=field("Random edge density (0–1)","0.28");seedField=field("Random seed (optional)","42");limitField=field("Exact limit (seconds)","3");manual=new TextArea("8 10 3\n1 2\n1 3\n2 4\n3 4\n4 5\n5 6\n5 7\n6 8\n7 8\n2 7");manual.setPrefRowCount(7);manual.setPromptText("Manual: N M R then M conflict pairs. Random: N R on first line.");p.getChildren().addAll(sectionLabel("INPUT GRAPH"),nField,rField,densityField,seedField,button("Generate random graph",this::generate),button("Load random input (N R)",this::loadRandomInput),button("Load manual edges (N M R)",this::loadManual),new Label("Manual: N M R, then u v per line.\nRandom: N R, using density above."),manual,button("Run DSatur",this::runGreedy),button("Run exact search",this::runExact),button("Compare both",this::compare),button("Export selected CSV",this::export),button("Reset",this::reset));return p;}
 private Node workspace(){VBox page=new VBox(14);page.setPadding(new Insets(0,0,0,16));HBox top=new HBox(12);top.setAlignment(Pos.CENTER_LEFT);resultChoice=new ComboBox<>(FXCollections.observableArrayList("Greedy DSatur","Exact search"));resultChoice.getSelectionModel().selectFirst();resultChoice.setOnAction(e->refresh());top.getChildren().addAll(heading("Conflict graph"),new Region(),new Label("View:"),resultChoice);HBox.setHgrow(top.getChildren().get(1),Priority.ALWAYS);graphPane=new VBox();graphPane.setMinHeight(370);graphPane.setStyle(card());stats=new Label("Load a graph to begin.");stats.setStyle("-fx-text-fill:#46556d;-fx-font-size:13px;");timetablePane=new VBox(8);timetablePane.setStyle(card());ScrollPane sc=new ScrollPane(timetablePane);sc.setFitToWidth(true);sc.setPrefViewportHeight(190);page.getChildren().addAll(top,graphPane,stats,sc);VBox.setVgrow(graphPane,Priority.ALWAYS);return page;}
 private TextField field(String label,String initial){TextField f=new TextField(initial);f.setPromptText(label);f.setMaxWidth(Double.MAX_VALUE);return f;}
 private String card(){return "-fx-background-color:white;-fx-background-radius:14;-fx-border-color:#e5eaf2;-fx-border-radius:14;-fx-padding:15;";}
 private Label heading(String text){Label l=new Label(text);l.setStyle("-fx-font-size:18px;-fx-font-weight:700;-fx-text-fill:#17243b;");return l;}
 private Label sectionLabel(String s){Label l=new Label(s);l.setStyle("-fx-font-size:11px;-fx-font-weight:800;-fx-text-fill:#71809a;");return l;}
 private Button button(String text,Runnable action){Button b=new Button(text);b.setMaxWidth(Double.MAX_VALUE);b.setStyle("-fx-background-color:#315efb;-fx-text-fill:white;-fx-font-weight:700;-fx-background-radius:8;-fx-padding:10;");b.setOnAction(e->{try{action.run();}catch(Exception ex){error(ex.getMessage());}});return b;}
 private void loadExample(){loadManual();}
 private void loadManual(){String[] lines=manual.getText().trim().split("\\R");String[] h=lines[0].trim().split("\\s+");if(h.length!=3)throw new IllegalArgumentException("First line must contain N M R.");int n=Integer.parseInt(h[0]),m=Integer.parseInt(h[1]);capacity=Integer.parseInt(h[2]);if(n<1||capacity<1||m<0||m>n*(n-1)/2||lines.length-1<m)throw new IllegalArgumentException("Invalid N, M, R, or missing edge lines.");ConflictGraph g=new ConflictGraph(n);for(int i=1;i<=m;i++){String[] e=lines[i].trim().split("\\s+");if(e.length!=2)throw new IllegalArgumentException("Edge line "+(i+1)+" must contain two course ids.");g.addConflict(Integer.parseInt(e[0]),Integer.parseInt(e[1]));}graph=g;nField.setText(""+n);rField.setText(""+capacity);greedy=exact=null;refresh();status.setText("Loaded "+n+" courses and "+g.edgeCount()+" unique conflicts.");}
 private void loadRandomInput(){String[] lines=manual.getText().trim().split("\\R");String[] h=lines[0].trim().split("\\s+");if(h.length!=2)throw new IllegalArgumentException("Random input first line must contain N R.");nField.setText(h[0]);rField.setText(h[1]);generate();}
 private void generate(){int n=Integer.parseInt(nField.getText()),r=Integer.parseInt(rField.getText());double d=Double.parseDouble(densityField.getText());long seed=seedField.getText().isBlank()?System.nanoTime():Long.parseLong(seedField.getText());graph=GraphGenerator.random(n,d,seed);capacity=r;greedy=exact=null;refresh();status.setText("Generated "+n+" courses and "+graph.edgeCount()+" conflicts (seed "+seed+").");}
 private void ensureGraph(){if(graph==null)loadManual();}
 private void runGreedy(){ensureGraph();greedy=new DSaturSolver().solve(graph,capacity);resultChoice.getSelectionModel().selectFirst();refresh();status.setText(String.format(Locale.ROOT,"DSatur complete · %d slots · %.3f ms",greedy.slotCount(),greedy.elapsedMillis()));}
 private void runExact(){ensureGraph();if(greedy==null)greedy=new DSaturSolver().solve(graph,capacity);exact=new ExactSolver().solve(graph,capacity,Math.max(1,(long)(Double.parseDouble(limitField.getText())*1000)),greedy);resultChoice.getSelectionModel().select(1);refresh();status.setText("Exact search "+(exact.optimal()?"proved optimal":"timed out; best valid result shown")+" · "+exact.slotCount()+" slots · "+String.format(Locale.ROOT,"%.3f ms",exact.elapsedMillis()));}
 private void compare(){runGreedy();runExact();}
 private Timetable selected(){return resultChoice.getSelectionModel().getSelectedIndex()==1?exact:greedy;}
 private void refresh(){if(graphPane==null||graph==null)return;Timetable t=selected();if(t==null&&greedy!=null)t=greedy;graphPane.getChildren().setAll(drawGraph(t));timetablePane.getChildren().clear();timetablePane.getChildren().add(heading("Timetable · "+(t==null?"not scheduled":t.slotCount()+" slots")));if(t!=null)for(int s=0;s<t.bySlot().size();s++){HBox row=new HBox(8);row.setAlignment(Pos.CENTER_LEFT);Label slot=new Label("SLOT "+(s+1));slot.setPrefWidth(66);slot.setStyle("-fx-font-weight:800;-fx-text-fill:#53627a;");row.getChildren().add(slot);for(int c:t.bySlot().get(s)){Label course=new Label("Course "+c);course.setPadding(new Insets(8,12,8,12));course.setTextFill(Color.WHITE);course.setStyle("-fx-background-color:"+color(s)+";-fx-background-radius:7;-fx-font-weight:700;");row.getChildren().add(course);}timetablePane.getChildren().add(row);}String g=greedy==null?"—":greedy.slotCount()+" slots / "+String.format(Locale.ROOT,"%.2f ms",greedy.elapsedMillis())+" / valid / optimality not guaranteed";String x=exact==null?"—":exact.slotCount()+" slots / "+String.format(Locale.ROOT,"%.2f ms",exact.elapsedMillis())+(exact.optimal()?" / valid / proven optimal":" / valid / optimality unproven (time limit)");stats.setText("Courses: "+graph.size()+"   Conflicts: "+graph.edgeCount()+"   Hall capacity: "+capacity+"   |   DSatur: "+g+"   |   Exact: "+x);}
 private String color(int s){String[] c={"#315efb","#e45a79","#10a680","#8a5cf6","#ef9c32","#169dbc","#ba4fbd","#718096"};return c[s%c.length];}
 private Node drawGraph(Timetable t){Pane pane=new Pane();pane.setPrefHeight(370);int n=graph.size();double w=700,h=340,cx=w/2,cy=h/2,rad=Math.min(140,70+n*3);double[] xs=new double[n],ys=new double[n];for(int i=0;i<n;i++){double a=-Math.PI/2+2*Math.PI*i/n;xs[i]=cx+rad*Math.cos(a);ys[i]=cy+rad*Math.sin(a);}for(int i=1;i<=n;i++)for(int j:graph.neighbours(i))if(j+1>i){Line line=new Line(xs[i-1],ys[i-1],xs[j],ys[j]);line.setStroke(Color.web("#cbd4e2"));line.setStrokeWidth(1.5);pane.getChildren().add(line);}for(int i=0;i<n;i++){int slot=t==null?-1:t.assignments()[i];Circle node=new Circle(xs[i],ys[i],20,slot<0?Color.web("#91a0b5"):Color.web(color(slot)));node.setStroke(Color.WHITE);node.setStrokeWidth(3);Label label=new Label(""+(i+1));label.setTextFill(Color.WHITE);label.setStyle("-fx-font-weight:800;");label.setLayoutX(xs[i]-4);label.setLayoutY(ys[i]-8);pane.getChildren().addAll(node,label);}HBox legend=new HBox(9);legend.setPadding(new Insets(5,0,0,0));if(t!=null)for(int s=0;s<t.slotCount();s++){Label l=new Label("● Slot "+(s+1));l.setTextFill(Color.web(color(s)));legend.getChildren().add(l);}VBox wrap=new VBox(pane,legend);wrap.setStyle(card());return wrap;}
 private void export(){Timetable t=selected();if(t==null)throw new IllegalStateException("Run an algorithm before exporting.");FileChooser fc=new FileChooser();fc.setTitle("Export timetable CSV");fc.setInitialFileName("exam-timetable.csv");fc.getExtensionFilters().add(new FileChooser.ExtensionFilter("CSV files","*.csv"));java.io.File f=fc.showSaveDialog(root.getScene().getWindow());if(f!=null){try{CSVExporter.write(Path.of(f.toURI()),t,capacity);status.setText("Exported "+f.getName()+".");}catch(java.io.IOException e){throw new IllegalStateException("Could not write the CSV file: "+e.getMessage(),e);}}}
 private void reset(){graph=null;greedy=exact=null;manual.clear();graphPane.getChildren().clear();timetablePane.getChildren().clear();stats.setText("Load a graph to begin.");status.setText("Reset complete.");}
 private void error(String msg){new Alert(Alert.AlertType.ERROR,"Could not complete: "+msg,ButtonType.OK).showAndWait();}
 private Button benchmarkButton(){return button("Run benchmark (N = 5, 10, 15, 20, 25, 30)",()->{LineChart<Number,Number> slots=chart("Slots used","Courses","Slots"),times=chart("Execution time (ms)","Courses","Milliseconds");XYChart.Series<Number,Number> gs=new XYChart.Series<>(),es=new XYChart.Series<>(),gt=new XYChart.Series<>(),et=new XYChart.Series<>();gs.setName("DSatur");es.setName("Exact");gt.setName("DSatur");et.setName("Exact");for(int n:new int[]{5,10,15,20,25,30}){ConflictGraph g=GraphGenerator.random(n,.25,1234+n);Timetable a=new DSaturSolver().solve(g,3),b=new ExactSolver().solve(g,3,1000,a);gs.getData().add(new XYChart.Data<>(n,a.slotCount()));es.getData().add(new XYChart.Data<>(n,b.slotCount()));gt.getData().add(new XYChart.Data<>(n,a.elapsedMillis()));et.getData().add(new XYChart.Data<>(n,b.elapsedMillis()));}slots.getData().addAll(gs,es);times.getData().addAll(gt,et);VBox box=new VBox(12,new Label("Same graph per pair · density 0.25 · capacity 3 · exact limit 1 s per size"),slots,times);ScrollPane scroll=new ScrollPane(box);scroll.setFitToWidth(true);Tab t=new Tab("Benchmark results",scroll);tabs.getTabs().add(t);tabs.getSelectionModel().select(t);});}
 private LineChart<Number,Number> chart(String title,String x,String y){NumberAxis xa=new NumberAxis(),ya=new NumberAxis();xa.setLabel(x);ya.setLabel(y);LineChart<Number,Number> c=new LineChart<>(xa,ya);c.setTitle(title);c.setAnimated(false);c.setCreateSymbols(true);c.setPrefHeight(310);return c;}
 public static void main(String[] args){launch(args);}
}
